{
  "lesson_summary": "Today's lesson plans to teach students how to compare and order unlike fractions. It will introduce two methods: cross multiplication, using the example of $\\frac{2}{3}$ of Hira's bottle and $\\frac{3}{5}$ of a friend's bottle, and finding common denominators. The lesson will also cover ordering three or more fractions.",
  "questions": [
    {
      "index": 1,
      "slo_id": "S1",
      "level": "understand",
      "question": "When comparing $\\frac{2}{3}$ and $\\frac{3}{5}$ using cross multiplication, what are the two products you compare?",
      "options": [
        "10 and 9",
        "2 and 3",
        "3 and 5"
      ],
      "correct_index": 0,
      "explanation": "Cross multiplication involves multiplying the numerator of one fraction by the denominator of the other. For $\\frac{2}{3}$ and $\\frac{3}{5}$, the products are $2 \\times 5 = 10$ and $3 \\times 3 = 9$.",
      "selected_because": "The lesson's own example of cross-multiplication products.",
      "distractor_misconceptions": {
        "1": "Confuses numerators with cross products",
        "2": "Confuses denominators with cross products"
      },
      "option_feedback": {
        "correct": "You are right! The products from cross multiplication are 10 and 9. Comparing these tells you which fraction is larger.",
        "wrong": {
          "1": "These are the numerators of the fractions, not the products from cross multiplication. Remember, for $\\frac{2}{3}$ and $\\frac{3}{5}$, you multiply $2 \\times 5$ and $3 \\times 3$.",
          "2": "These are the denominators of the fractions, not the products from cross multiplication. When using cross multiplication, you multiply the numerator of one fraction by the denominator of the other."
        }
      },
      "figure": null,
      "figure_role": null
    }
  ]
}
